2. Removing Elements:The Stack class provides two different methods to remove elements and the methods are listed below:Clear() Method: The clear() is used to remove all the objects from the stack.Pop Method(): The pop() is used to removes the beginning element of the stack.Example: This example displays the contents of the stack before and after removal.
            C#

    // C# Program to remove elements
// from a stack
using System;
using System.Collections.Generic;

class Geeks {
    public static void Main(string[] args)
    {
        // Initialize a stack
        Stack<string> s = new Stack<string>();

        // Inserting elements into the s using Push()
        s.Push("Geeks");
        s.Push("For");
        s.Push("Geeks");
        s.Push("For");

        // Initial stack
        Console.WriteLine("Initial stack: ");
        foreach(var item in s) { 
          Console.WriteLine(item); 
        }

        // Removing the top element 
        // from the stack
        s.Pop();

        // Final s after removal
        Console.WriteLine("\nUpdated stack after Pop:");
        foreach(var item in s) { 
          Console.WriteLine(item); 
        }
    }
}

